export function buildReport(rows) {
  const valid = [];
  for (const r of rows) { if (r && typeof r.amount === 'number' && r.amount >= 0) valid.push(r); }
  let total = 0;
  for (const r of valid) total += r.amount;
  const lines = valid.map((r) => `${r.name}: ${r.amount.toFixed(2)}`);
  lines.push(`TOTAL: ${total.toFixed(2)}`);
  return lines.join('\n');
}

