import { validRows } from './validate.js';
export function buildReport(rows) {
  const valid = validRows(rows);
  const total = valid.reduce((s, r) => s + r.amount, 0);
  const lines = valid.map((r) => `${r.name}: ${r.amount.toFixed(2)}`);
  lines.push(`TOTAL: ${total.toFixed(2)}`);
  return lines.join('\n');
}
